export const DEFAULT_MEAL_TEMPLATES: MealTemplate[] = [{"id": "tg5", "category": "Завтрак", "name": "Ленивая овсянка с вишней и зернёным творогом", "kcal": 449, "p": 30, "f": 14, "c": 46, "portionNote": "На 1 порцию", "video": "video_files/IMG_0676.MP4", "ingredients": "Овсяные хлопья — 40 г, греческий йогурт 2% — 100 г, творог зернёный 5% — 130 г, молоко — 30 мл, семена чиа — 5 г, вишня замороженная — 80 г, мёд — 10 г.", "steps": "Выложить овсянку, йогурт, творог и семена чиа в контейнер, залить молоком. Добавить вишню и мёд, перемешать, закрыть крышкой и убрать в холодильник на ночь."}, {"id": "tg6", "category": "Завтрак", "name": "Нежная творожно-йогуртовая запеканка с вишней", "kcal": 264, "p": 24, "f": 9, "c": 20, "portionNote": "На всю порцию", "video": "video_files/IMG_0681.MP4", "ingredients": "Греческий йогурт — 230 г, яйцо — 1 шт., кукурузный крахмал — 10 г, сахзам по вкусу, замороженная вишня — 25–30 г.", "steps": "Перемешать йогурт, яйцо, крахмал и сахзам. Выложить сверху вишню и запекать в духовке 20–25 минут при 180 °C."}, {"id": "tg8", "category": "Завтрак", "name": "Овсяноблин «Сникерс» с карамелью и арахисом", "kcal": 425, "p": 42, "f": 6, "c": 48, "portionNote": "На 1 порцию", "video": "video_files/IMG_0684.MP4", "ingredients": "Блин: овсяные хлопья 50 г, яичный белок 100 г (3 шт.), кефир 1% 60 мл, какао 10 г, разрыхлитель, соль, подсластитель. Крем: мягкий творог 0.1% 120 г, протеиновый карамельный пудинг 50 г, арахисовая паста 10 г, солёная карамель 10 г.", "steps": "Смешать ингредиенты для блина и обжарить с двух сторон. Промазать кремом из мягкого творога и пудинга, добавить арахисовую пасту и карамель."}, {"id": "tg9", "category": "Десерты", "name": "ПП Наполеон на тесте фило (порция ~370 г)", "kcal": 370, "p": 37, "f": 11, "c": 44, "portionNote": "100 ккал / 100 г (Б 10 / Ж 3 / У 12)", "video": "video_files/IMG_0687.MP4", "ingredients": "Карамельный протеиновый пудинг Hype — 200 г, мягкий творог 6% — 120 г, тесто фило — 50–100 г, ягоды/фрукты по желанию.", "steps": "Подрумянить листы теста фило в духовке 5–10 минут при 180 °C. Смешать пудинг с мягким творогом, прослоить коржи и украсить ягодами."}, {"id": "tg14", "category": "Десерты", "name": "Шоколадно-грушевый ПП чизкейк (весь торт ~650 г)", "kcal": 652, "p": 39, "f": 20, "c": 79, "portionNote": "Весь торт (~100 ккал / 100 г)", "video": "video_files/IMG_0689.MP4", "ingredients": "Грушевое пюре — 250 г, греческий йогурт 2% — 250 г, яйца — 2 шт., кукурузный крахмал — 30 г, какао — 20 г, сахзам. Глазурь: тёмный шоколад б/с — 15 г, молоко 1.5% — 10 мл.", "steps": "Смешать основу венчиком, перелить в форму (12.5×7 см) и выпекать 50 минут при 180 °C. Остудить, убрать в холодильник на ночь, перед подачей полить растопленным шоколадом с молоком."}, {"id": "tg13", "category": "Выпечка", "name": "Крабовые пирожки с сыром (63 г белка)", "kcal": 674, "p": 63, "f": 34, "c": 23, "portionNote": "На всю порцию", "video": "video_files/IMG_0692.MP4", "ingredients": "Крабовые палочки — 200 г, сыр лёгкий — 100 г, яйцо варёное — 2 шт., яйцо сырое — 1 шт.", "steps": "Мелко нарезать крабовые палочки, натереть варёные яйца и сыр. Добавить сырое яйцо, перемешать, слепить пирожки и запекать 15–20 минут при 180 °C."}, {"id": "tg12", "category": "Салаты", "name": "Лёгкий крабовый салат с сыром и томатами (~425 г)", "kcal": 336, "p": 32, "f": 14, "c": 20, "portionNote": "Вся миска (79 ккал / 100 г)", "video": "video_files/IMG_0694.MP4", "ingredients": "Варёное яйцо — 1 шт., крабовые палочки — 100 г, помидоры — 100 г, сладкий перец — 100 г, лёгкий сыр — 40 г, сметана 10% — 30 г.", "steps": "Нарезать все ингредиенты кубиком и заправить сметаной 10% или лёгким майонезом."}, {"id": "tg18", "category": "Салаты", "name": "Белковый салат с копчёной грудкой и корейской морковью", "kcal": 328, "p": 40, "f": 10, "c": 20, "portionNote": "На 1 порцию (из 2)", "video": "video_files/IMG_0704.MP4", "ingredients": "На 2 порции: копчёная куриная грудка без кожи — 250 г, морковь по-корейски без масла — 250 г, кукуруза — 80 г, варёное яйцо — 2 шт., греческий йогурт — 60 г, красный лук, листовой салат, соль.", "steps": "Нарезать грудку, яйца и зелень, добавить морковь по-корейски и кукурузу, заправить греческим йогуртом."}, {"id": "tg15", "category": "Обед", "name": "Запеканка с куриным филе, картофелем и сырной шапкой (1/2 формы)", "kcal": 680, "p": 58, "f": 26, "c": 52, "portionNote": "Половина формы (~550 г)", "video": "video_files/IMG_0696.MP4", "ingredients": "На форму: куриное филе — 450 г, картофель — 4–5 шт., лук — 1 шт., помидоры — 2 шт., сметана — 150 мл, сыр твёрдый — 100 г, масло — 1 ст. л., паприка, чеснок, соль.", "steps": "Выложить слоями лук и картофель, сверху куриное филе в специях. Запекать под фольгой 20–25 мин при 200 °C, затем залить смесью помидоров, сметаны и сыра и запечь ещё 10–15 мин."}, {"id": "tg16", "category": "Обед", "name": "Картофельная запеканка с куриной ветчиной и моцареллой", "kcal": 423, "p": 35, "f": 19, "c": 26, "portionNote": "На 1 порцию", "video": "video_files/IMG_0699.MP4", "ingredients": "Отварной картофель — 150 г, нежирная куриная ветчина — 50 г, яйца — 2 шт., красный лук, сыр моцарелла — 25 г, соль и специи.", "steps": "Размять картофель вилкой, смешать с яйцами, ветчиной, луком и половиной сыра. Посыпать оставшейся моцареллой и запекать 20 минут при 200 °C."}, {"id": "tg19", "category": "Обед", "name": "Паста с креветками, песто, мягким творогом и пармезаном (1/2 рецепта)", "kcal": 634, "p": 65, "f": 18, "c": 53, "portionNote": "Половина блюда (65 г белка)", "video": "video_files/IMG_0706.MP4", "ingredients": "На 2 порции: креветки — 500 г, мягкий творог — 120 г, шпинат, томаты черри — 100 г, соус песто — 1 ч. л., макароны (сух.) — 120 г, пармезан — 50 г, соль, перец.", "steps": "Запечь креветки, творог, шпинат, черри и песто 15 минут при 180 °C. Перемешать с отваренными макаронами и пармезаном, вернуть в духовку на 3–5 минут."}, {"id": "tg20", "category": "Обед", "name": "Боул с рисом, креветками, авокадо и йогуртовым соусом", "kcal": 523, "p": 24, "f": 12, "c": 74, "portionNote": "На 1 порцию", "video": "video_files/IMG_0708.MP4", "ingredients": "Рис сухой — 50 г, авокадо — 50 г, креветки — 70 г, кукуруза — 100 г, огурец — 1 шт. Соус: греческий йогурт — 50 г, соевый соус — 15 г.", "steps": "Отварить рис, выложить в глубокую тарелку, добавить креветки, авокадо, кукурузу и огурец. Полить соусом из йогурта и соевого соуса."}, {"id": "tg17", "category": "Ужин", "name": "Фаршированные перцы с куриной грудкой и моцареллой", "kcal": 560, "p": 76, "f": 18, "c": 16, "portionNote": "На всю порцию (76 г белка)", "video": "video_files/IMG_0701.MP4", "ingredients": "Куриная грудка — 400 г, мини-моцарелла — 1 упаковка (~100 г), яйцо — 1 шт., сладкий перец, петрушка/зелень, соевый соус, специи.", "steps": "Нафаршировать половинки сладкого перца рубленой куриной грудкой с яйцом, зеленью и моцареллой. Запекать под фольгой 40 мин при 210 °C, затем ещё 10 мин без фольги."}, {"id": "tg21", "category": "Ужин", "name": "Ленивые роллы с тунцом и рикоттой (60 г белка)", "kcal": 545, "p": 60, "f": 14, "c": 46, "portionNote": "На 1 порцию (60 г белка)", "video": "video_files/aaa7ba58c70545cba2014d1803e97d99.mp4", "ingredients": "Рис (в пакетиках, сух.) — 62 г, тунец — 135 г, рикотта — 75 г, мягкий творог Савушкин — 120 г, лёгкий сыр — 30 г, чипсы нори — 5 г.", "steps": "Отварить рис, смешать с размятым тунцом, рикоттой, мягким творогом и натёртым лёгким сыром. Подавать с хрустящими чипсами нори."}, {"id": "m_tvorog", "category": "Десерты", "name": "Творог 500г + молоко + сгущенка (Классика)", "kcal": 780, "p": 84, "f": 18, "c": 68, "portionNote": "Массонаборный хит", "video": "", "ingredients": "Творог обезжиренный/2% — 500 г, молоко — 100 мл, сгущённое молоко — 40 г.", "steps": "Залить сухой творог молоком, добавить сгущёнку и перемешать до кремовой консистенции."}];

